//   cat  el valor de OSM (mall, park, university...); es para el icono
//   loc  id 1..20 de la localidad en la que cae, ya resuelto aqui
//   bi   posicion del sector dentro de esa localidad (ver GDF_BARRIOS_GEO).
//        Sin `bi` el sitio cae en un hueco entre sectores y vale su
//        localidad sola, que es el mismo caso que un clic en un hueco.
